                4.0 * Series(1, _n) -
                2.0 * Series(4, _n) -
                1.0 * Series(5, _n) -
                1.0 * Series(6, _n);

            x -= Math.Floor(x);
            int digit = (int)(16.0 * x) & 0xF;
            _n++;                         // internal advance inside math engine
            return digit;
        }

