script_py = r"""#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
ffr_experiments.py — Frame–Flow Reproducibility Pack (standalone)
Usage:
  python ffr_experiments.py bbp --N 120 --prec 1200 --csv bbp.csv
  python ffr_experiments.py sha --trials 20000 --csv sha.csv
  python ffr_experiments.py path --trials 5000 --csv path.csv
  python ffr_experiments.py couple --dim 64 --trials 2000 --csv couple.csv

Dependencies: mpmath, numpy, pandas, matplotlib (optional for plotting)
"""
import argparse, math, random, hashlib
from typing import List, Tuple
import numpy as np, pandas as pd
try:
    import mpmath as mp
except Exception as e:
    raise SystemExit("Please: pip install mpmath\n" + str(e))

def leading_zero_run_decimal(x, max_scan: int = 10000) -> int:
    s = mp.nstr(x, n=max_scan+5)  # "0.xxx..."
    if "0." not in s:
        return 0
    tail = s.split("0.", 1)[1]
    run = 0
    for ch in tail:
        if ch == '0':
            run += 1
        else:
            break
    return run

def sha256_bytes(b: bytes) -> bytes:
    return hashlib.sha256(b).digest()

def sha256_variants_message(length_mode: str, payload: bytes) -> bytes:
    """
    Forge a single-block message with controlled 'length field' behavior.
    length_mode:
      - 'std': correct SHA-256 single-block padding
      - 'nolength': drop the 64-bit length (replace with zeros)
      - 'wrongend': write length with wrong endianness
    """
    ml = len(payload) * 8  # bit length
    pad_len = 64 - ((len(payload) + 1 + 8) % 64)
    msg = payload + b'\x80' + (b'\x00' * pad_len)
    if length_mode == 'std':
        msg += ml.to_bytes(8, 'big')
    elif length_mode == 'nolength':
        msg += b'\x00' * 8
    elif length_mode == 'wrongend':
        msg += ml.to_bytes(8, 'little')
    else:
        raise ValueError("length_mode")
    return msg

def digest_trace_signature(d: bytes) -> dict:
    bits = ''.join(f'{byte:08b}' for byte in d)
    pop = bits.count('1')
    runs = []
    cur = bits[0]; cnt = 1
    for b in bits[1:]:
        if b == cur:
            cnt += 1
        else:
            runs.append(cnt); cur = b; cnt = 1
    runs.append(cnt)
    arr = np.array(runs)
    # simple, reproducible features
    # byte entropy (rough proxy)
    hist = np.bincount(list(d), minlength=256).astype(float)
    p = hist / hist.sum()
    with np.errstate(divide='ignore', invalid='ignore'):
        ent = -(p * np.log2(np.where(p>0, p, 1))).sum()
    return {
        "popcount": pop,
        "run_mean": float(arr.mean()),
        "run_std": float(arr.std(ddof=1) if len(arr)>1 else 0.0),
        "byte_entropy": float(ent),
    }

# ---------- Experiments ----------

def bbp_staircase(N: int, prec: int) -> pd.DataFrame:
    mp.mp.dps = int(prec)
    rows = []
    for n in range(N+1):
        val = mp.fmod(mp.pi / (mp.power(16, n)), 1)
        z = leading_zero_run_decimal(val, max_scan=min(prec-5, 8000))
        rows.append({"n": n, "value": mp.nstr(val, n=min(prec, 120)), "leading_zeros": z})
    return pd.DataFrame(rows)

def sha_closure_suite(trials: int = 10000, payload_len: int = 24) -> pd.DataFrame:
    rng = random.Random(0xC0FFEE)
    modes = ["std", "nolength", "wrongend"]
    rows = []
    for t in range(trials):
        p = bytes(rng.getrandbits(8) for _ in range(payload_len))
        base = sha256_bytes(sha256_variants_message("std", p))
        base_sig = digest_trace_signature(base)
        for m in modes:
            msg = sha256_variants_message(m, p)
            dig = sha256_bytes(msg)
            sig = digest_trace_signature(dig)
            rows.append({
                "trial": t, "mode": m,
                "popcount": sig["popcount"], "run_mean": sig["run_mean"],
                "run_std": sig["run_std"], "byte_entropy": sig["byte_entropy"],
                "delta_pop": sig["popcount"] - base_sig["popcount"],
                "delta_run_mean": sig["run_mean"] - base_sig["run_mean"],
                "delta_run_std": sig["run_std"] - base_sig["run_std"],
                "delta_ent": sig["byte_entropy"] - base_sig["byte_entropy"],
            })
    return pd.DataFrame(rows)

def path_dependence_probe(trials: int = 5000) -> pd.DataFrame:
    rng = random.Random(12345)
    rows = []
    for t in range(trials):
        a = rng.getrandbits(32).to_bytes(4,'big')
        b = rng.getrandbits(32).to_bytes(4,'big')
        d1 = sha256_bytes(a+b)
        d2 = sha256_bytes(b+a)
        s1 = digest_trace_signature(d1)
        s2 = digest_trace_signature(d2)
        rows.append({"trial": t, "pair":"(a,b)", **s1})
        rows.append({"trial": t, "pair":"(b,a)", **s2})
    return pd.DataFrame(rows)

def resonant_induction_toy(dim: int=64, trials: int=2000, seed: int=7) -> pd.DataFrame:
    rng = np.random.default_rng(seed)
    target = rng.integers(0, 2, size=dim, dtype=np.int8)
    def score(dig: bytes) -> int:
        bits = np.unpackbits(np.frombuffer(dig, dtype=np.uint8))
        L = min(len(bits), dim)
        return int(np.sum(bits[:L] == target[:L]))

    trials_data = []
    # Adaptive solver
    for t in range(trials):
        x = rng.integers(0,256,size=32,dtype=np.uint8)
        prev = score(sha256_bytes(x.tobytes()))
        for step in range(256):
            deficit = dim - prev
            k = max(1, min(4, deficit//8 + 1))
            idx = rng.choice(32, size=k, replace=False)
            cand = x.copy()
            for i in idx:
                cand[i] ^= rng.integers(1,256)
            s = score(sha256_bytes(cand.tobytes()))
            if s >= prev:
                x, prev = cand, s
            if prev >= int(0.75*dim):
                trials_data.append({"solver":"resonant","steps": step+1, "score": prev})
                break
        else:
            trials_data.append({"solver":"resonant","steps": 256, "score": prev})

    # Tuned random walk
    for t in range(trials):
        x = rng.integers(0,256,size=32,dtype=np.uint8)
        prev = score(sha256_bytes(x.tobytes()))
        for step in range(256):
            i = rng.integers(0,32)
            cand = x.copy(); cand[i] ^= rng.integers(1,256)
            s = score(sha256_bytes(cand.tobytes()))
            if rng.random() < 0.5:
                x, prev = cand, s
            if prev >= int(0.75*dim):
                trials_data.append({"solver":"tuned-walk","steps": step+1, "score": prev})
                break
        else:
            trials_data.append({"solver":"tuned-walk","steps": 256, "score": prev})

    # Random baseline
    for t in range(trials):
        prev = score(sha256_bytes(rng.integers(0,256,size=32,dtype=np.uint8).tobytes()))
        trials_data.append({"solver":"random","steps": 1, "score": prev})

    return pd.DataFrame(trials_data)

def main():
    ap = argparse.ArgumentParser()
    sub = ap.add_subparsers(dest="cmd", required=True)

    sp = sub.add_parser("bbp"); sp.add_argument("--N", type=int, default=120)
    sp.add_argument("--prec", type=int, default=1200); sp.add_argument("--csv", type=str, default=None)

    sp2 = sub.add_parser("sha"); sp2.add_argument("--trials", type=int, default=20000); sp2.add_argument("--csv", type=str, default=None)

    sp3 = sub.add_parser("path"); sp3.add_argument("--trials", type=int, default=5000); sp3.add_argument("--csv", type=str, default=None)

    sp4 = sub.add_parser("couple"); sp4.add_argument("--dim", type=int, default=64); sp4.add_argument("--trials", type=int, default=2000); sp4.add_argument("--csv", type=str, default=None)

    args = ap.parse_args()

    if args.cmd == "bbp":
        df = bbp_staircase(args.N, args.prec)
        if args.csv: df.to_csv(args.csv, index=False)
        else: print(df.head(12).to_string(index=False))

    elif args.cmd == "sha":
        df = sha_closure_suite(args.trials)
        if args.csv: df.to_csv(args.csv, index=False)
        print(df.groupby("mode")[["delta_pop","delta_run_mean","delta_run_std","delta_ent"]].mean())

    elif args.cmd == "path":
        df = path_dependence_probe(args.trials)
        if args.csv: df.to_csv(args.csv, index=False)
        print(df.groupby("pair")[["popcount","run_mean","run_std","byte_entropy"]].mean())

    elif args.cmd == "couple":
        df = resonant_induction_toy(args.dim, args.trials)
        if args.csv: df.to_csv(args.csv, index=False)
        print(df.groupby("solver")[["steps","score"]].mean())

if __name__ == "__main__":
    main()
